update.foreach:
update vm_recorder_device_info_t set device_status = #{item.resourceStatus}, area_code = #{item.adminArea}, adm_code = #{item.dept}, modifier = #{item.updateBy},
access_node = #{item.locationCode},
delete_flag = #{item.delFlag}, update_time = DATE_FORMAT(#{item.updateTime}, '%Y-%m-%d %H:%i:%S') where device_code = #{item.deviceCode}
